<script lang="ts">import type {ResolvedEntityContext,RepositoryState} from '../../lib/model/entityTypes';export let context:ResolvedEntityContext;export let repository:RepositoryState|null=null;export let codexInfo:any=null;function elapsed(runtime:any){const end=runtime.completedAt?Date.parse(runtime.completedAt):Date.now();const start=Date.parse(runtime.startedAt);if(!Number.isFinite(start))return '—';const seconds=Math.max(0,Math.floor((end-start)/1000));return `${Math.floor(seconds/60)}m ${seconds%60}s`}</script>
<div data-testid="entity-evidence" data-entity-type={context.type}>
{#if context.type==='milestone'}
  <div class="evidence-intro"><span class="live-dot"></span><strong>里程碑汇总证据</strong></div>
  <div class="evidence-list milestone-metrics"><div><span>Progress</span><b class="metric-value">{context.progress!==null?`${context.progress}%`:'—'}</b></div><div><span>Work Packages</span><b class="metric-value">{context.summary.workPackages??'—'}</b></div><div><span>Complete</span><b class="metric-value">{context.summary.complete??'—'}</b></div><div><span>Waiting / Active</span><b class="metric-value">{context.summary.waiting??'—'}</b></div><div><span>Blocked</span><b class="metric-value">{context.summary.blocked??'—'}</b></div><div><span>Pull Requests</span><b class="metric-value">{context.summary.pullRequests??'—'}</b></div></div>
  <div class="auth-card"><span class="kicker">BLOCKERS</span><strong>{context.blockers.length?'存在阻塞':'无已记录阻塞'}</strong><p>{context.blockers.join('；')||'当前来源未报告阻塞。'}</p></div>
  <div class="auth-card"><span class="kicker">RECENT ACTIVITY</span><strong>{context.recentActivity}</strong><p>{context.nextAction}</p></div>
{:else if context.type==='work_package'}
  <div class="evidence-intro"><span class="live-dot"></span><strong>当前 WP 真实证据</strong></div>
  {#if repository}<div class="evidence-list">{#each [['Repository',repository.repository],['Current Branch',repository.branch],['Current HEAD',repository.head],['Worktree',repository.worktree]] as row}<div><span>{row[0]}</span><code>{row[1]}</code></div>{/each}</div>{/if}
  <div class="auth-card"><span class="kicker">OWNER AUTHORIZATION</span>{#if context.authorization.state==='VALID'&&context.authorization.record}<strong>Owner 授权 · 已授权</strong><p>Work Package: {context.authorization.record.workPackageId}<br/>Branch: {context.authorization.record.branch}<br/>Authorized HEAD: {context.authorization.record.headShaAtAuthorization.slice(0,7)}<br/>Current HEAD: {repository?.head.slice(0,7)??'UNAVAILABLE'}</p>{:else}<strong>当前 WP 无有效授权</strong><p>{context.authorization.reasonCode??context.authorization.state}</p>{/if}</div>
  <div class="auth-card runtime-card"><span class="kicker">CODEX RUNTIME</span>{#if context.runtime}<strong>{context.runtime.phase}</strong><p>WP: {context.runtime.workPackageId}<br/>Execution Type: {context.runtime.executionType??'—'}<br/>Sandbox: {context.runtime.sandboxMode??'—'}<br/>Run ID: {context.runtime.runId}<br/>PID: {context.runtime.pid??'—'} · {context.runtime.pidAlive===true?'ALIVE':'DEAD / UNKNOWN'}<br/>Thread: {context.runtime.threadId??'等待 thread.started'}<br/>Elapsed: {elapsed(context.runtime)}<br/>Last activity: {context.runtime.lastActivityAt}<br/>Exit code: {context.runtime.exitCode??'—'}<br/>Implementation: {context.runtime.implementationResult??'等待进程结束'}<br/>Commands: {context.runtime.commandExecutionCount??0} · File changes: {context.runtime.fileChangeEventCount??0} · Tool calls: {context.runtime.toolCallCount??0}</p>{#if context.runtime.finalAgentMessage}<small>Final message: <code>{context.runtime.finalAgentMessage}</code></small>{:else if context.runtime.implementationResult==='NO_IMPLEMENTATION_CHANGE'}<small>UNJUSTIFIED_NO_CHANGE</small>{/if}{#if context.runtime.healthWarning}<small>Health warning: <code>{context.runtime.healthWarning}</code></small>{/if}{#if context.runtime.stderr}<small>stderr: <code>{context.runtime.stderr}</code></small>{/if}{:else}<strong>当前 WP 无匹配 Runtime</strong><p>Codex CLI · {codexInfo?.available?'AVAILABLE':'UNAVAILABLE'}</p>{/if}</div>
  <div class="runtime-list"><div><span>Writer Lock（仓库级）</span><b>{context.writerLock.status==='HELD'?'HELD / 已持有':context.writerLock.status==='NOT_HELD'?'NOT_HELD / 已释放':'UNAVAILABLE'}</b></div><div><span>Validation</span><b>{context.lifecycle.stages.find(stage=>stage.id==='VALIDATION')?.status}</b></div><div><span>Human UAT</span><b>{context.humanUat?.status??'UNAVAILABLE / ABSENT'}</b></div><div><span>Related PRs</span><b>{context.relatedPullRequests.length}</b></div></div>
{:else}<div class="evidence-intro"><strong>{context.record?.fixture?'DEMO · LOCAL FIXTURE':'PR evidence unavailable'}</strong></div><div class="runtime-list"><div><span>Source</span><b>{context.record?.fixture?'DEMO · LOCAL FIXTURE':'PRODUCTION'}</b></div><div><span>Parent WP</span><b>{context.parentWorkPackageId??'UNAVAILABLE'}</b></div><div><span>Production PR</span><b>{context.record?.fixture?'ABSENT':'UNAVAILABLE'}</b></div><div><span>GitHub PR</span><b>{context.record?.url??'NOT_BOUND'}</b></div><div><span>Exact-head CI</span><b>{context.record?.ciEvidence??'NOT_RUN'}</b></div><div><span>Merge</span><b>{context.record?.mergeResult??'NOT_RUN'}</b></div><div><span>PR HEAD</span><b>{context.record?.headSha??'UNAVAILABLE'}</b></div><div><span>Files changed</span><b>{context.record?.filesChanged??'—'}</b></div></div>{/if}
</div>
